// Python's `str.casefold()`, which the connectors' discovery searches match names with (their connector.py
// `discover`). JavaScript has no case folding: `toLowerCase()` keeps "ß", "ς" and "ﬁ" as they are, leaves
// Cherokee small letters, which Python folds to capitals, and depends on the runtime's ICU. So this reads
// Python's own table (casefold-table.ts, generated from Python 3.14's Unicode 16.0), one code point at a time
// as Python folds, and is the same in every runtime. Lone surrogates, which Python leaves alone, are kept too.
// The table is regenerated by test/fixtures/connectors/xero/generate.py --table, and
// test/unit/connectors-xero-vectors.test.ts compares this with Python for every code point.

import { LONGER, RUNS } from "./casefold-table.ts";

let table: Map<number, string> | null = null;

function folds(): Map<number, string> {
	if (table !== null) return table;
	const built = new Map<number, string>();
	for (let at = 0; at < RUNS.length; at += 4) {
		const [first, last, offset, step] = RUNS.slice(at, at + 4) as [number, number, number, number];
		for (let point = first; point <= last; point += step) built.set(point, String.fromCodePoint(point + offset));
	}
	for (const [point, ...folded] of LONGER) built.set(point as number, String.fromCodePoint(...folded));
	table = built;
	return built;
}

/** `text.casefold()`. */
export function casefold(text: string): string {
	const map = folds();
	let out = "";
	for (const char of text) out += map.get(char.codePointAt(0) as number) ?? char;
	return out;
}
